 1| //! 操作符模块 —— rx-rust 响应式库的操作符集合。
 2| //!
 3| //! 所有操作符均实现为**自由函数**（free function），而非 Observable 的方法，
 4| //! 这样便于函数式组合（`pipe` 风格）：
 5| //!
 6| //! ```
 7| //! use rx_rust::operators::{filter::distinct, utility::tap, composite::zip};
 8| //! use rx_rust::prelude::*;
 9| //!
10| //! let result = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
11| //! let r = result.clone();
12| //!
13| //! // 函数式组合（先 filter，后 tap，再 zip）
14| //! let src = Observable::<i32, ()>::from_iter(vec![1, 2, 3, 2, 1]);
15| //! let filtered = distinct(&src);
16| //! let tapped = tap(&filtered, |x| println!("tapped: {x}"));
17| //! zip(&tapped, &Observable::<i32, ()>::from_iter(vec![10, 20, 30]))
18| //!     .subscribe_on_next(move |(a, b)| r.lock().unwrap().push((a, b)));
19| //! ```
20| //!
21| //! 也可直接在 Observable 上调用方法链：
22| //!
23| //! ```
24| //! use rx_rust::prelude::*;
25| //!
26| //! let result = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
27| //! let r = result.clone();
28| //! Observable::<i32, ()>::from_iter(vec![1, 2, 3, 2, 1])
29| //!     .distinct()
30| //!     .tap(|x| println!("tapped: {x}"))
31| //!     .subscribe_on_next(move |x| r.lock().unwrap().push(x));
32| //! ```
