   7| // ============================================================================
   8| // Observable —— 可观察对象
   9| // ============================================================================
  10| 
  11| pub struct Observable<T, E = ()> {
  12|     pub(crate) subscribe_fn: Arc<dyn Fn(Box<dyn Observer<T, E>>) -> Subscription + Send + Sync>,
  13| }
  14| 
  15| impl<T, E> Clone for Observable<T, E> {
  16|     fn clone(&self) -> Self { Self { subscribe_fn: self.subscribe_fn.clone() } }
  17| }
  18| 
  19| // ============================================================================
  20| // Callbacks —— 用三个闭包实现 Observer
  21| // ============================================================================
  22| 
  23| pub struct Callbacks<T, E> {
  24|     pub on_next: Mutex<Box<dyn FnMut(T) + Send + Sync>>,
  25|     pub on_error: Mutex<Box<dyn FnMut(E) + Send + Sync>>,
  26|     pub on_completed: Mutex<Box<dyn FnMut() + Send + Sync>>,
  27| }
  28| 
  29| impl<T, E> Observer<T, E> for Callbacks<T, E> {
  30|     fn on_next(&self, value: T) { if let Ok(mut f) = self.on_next.lock() { (f)(value); } }
  31|     fn on_error(&self, err: E) { if let Ok(mut f) = self.on_error.lock() { (f)(err); } }
  32|     fn on_completed(&self) { if let Ok(mut f) = self.on_completed.lock() { (f)(); } }
  33| }
  34| 
  35| // ============================================================================
  36| // 订阅入口 + 工厂函数（通用，不要求 T: Clone）
  37| // ============================================================================
  38| 
  39| impl<T, E> Observable<T, E>
  40| where
  41|     T: Send + Sync + 'static,
  42|     E: Send + Sync + 'static,
  43| {
  44|     pub(crate) fn new_impl<F>(f: F) -> Self
  45|     where F: Fn(Box<dyn Observer<T, E>>) -> Subscription + Send + Sync + 'static,
  46|     { Self { subscribe_fn: Arc::new(f) } }
  47| 
  48|     pub fn subscribe<O>(&self, observer: O) -> Subscription
  49|     where O: Observer<T, E> + 'static,
  50|     { (self.subscribe_fn)(Box::new(observer)) }
  51| 
  52|     pub fn subscribe_on_next<F>(&self, on_next: F) -> Subscription
  53|     where F: FnMut(T) + Send + Sync + 'static,
  54|     {
  55|         self.subscribe(Callbacks {
  56|             on_next: Mutex::new(Box::new(on_next)),
  57|             on_error: Mutex::new(Box::new(|_| {})),
  58|             on_completed: Mutex::new(Box::new(|| {})),
  59|         })
  60|     }
  61| 
  62|     // —— from_iter（要求 T: Clone 以便 Vec 能复用）——
  63|     // 放在这里以便 Observable::<T, E>::from_iter 推断 E 时更灵活。
  64|     pub fn from_iter<I>(iter: I) -> Self
  65|     where
  66|         T: Clone,
  67|         I: IntoIterator<Item = T>,
  68|         I::IntoIter: Send + Sync + 'static,
  69|     {
  70|         let vec: Vec<T> = iter.into_iter().collect();
  71|         Self::new_impl(move |observer| {
  72|             for v in &vec { observer.on_next(v.clone()); }
  73|             observer.on_completed();
  74|             Subscription::empty()
  75|         })
  76|     }
  77| 
  78|     pub fn of(value: T) -> Self
  79|     where T: Clone,
  80|     {
  81|         Self::new_impl(move |observer| {
  82|             observer.on_next(value.clone());
  83|             observer.on_completed();
  84|             Subscription::empty()
  85|         })
  86|     }
  87| 
  88|     pub fn repeat(value: T, count: usize) -> Self
  89|     where T: Clone,
  90|     {
  91|         Self::new_impl(move |observer| {
  92|             for _ in 0..count { observer.on_next(value.clone()); }
  93|             observer.on_completed();
  94|             Subscription::empty()
  95|         })
  96|     }
  97| 
  98|     // —— 通用工厂（不要求 T: Clone）——
  99|     pub fn empty() -> Self {
 100|         Self::new_impl(|observer| { observer.on_completed(); Subscription::empty() })
 101|     }
 102| 
 103|     pub fn never() -> Self {
 104|         Self::new_impl(|_| Subscription::empty())
 105|     }
 106| }
