 108| impl<T, E> Observable<T, E>
 109| where
 110|     T: Send + Sync + 'static,
 111|     E: Send + Sync + Clone + 'static,
 112| {
 113|     pub fn error(err: E) -> Self {
 114|         Self::new_impl(move |observer| { observer.on_error(err.clone()); Subscription::empty() })
 115|     }
