 117|     pub fn range(start: i64, count: i64) -> Observable<i64, E> {
 118|         Observable::<i64, E>::new_impl(move |observer| {
 119|             for i in 0..count { observer.on_next(start + i); }
 120|             observer.on_completed();
 121|             Subscription::empty()
 122|         })
 123|     }
 124| }
