 126| // ============================================================================
 127| // 工具：把下游观察者包装成共享 Arc
 128| // ============================================================================
 129| 
 130| fn wrap_downstream<T, E>(downstream: Box<dyn Observer<T, E>>) -> Arc<dyn Observer<T, E>>
 131| where
 132|     T: Send + Sync + 'static,
 133|     E: Send + Sync + 'static,
 134| {
 135|     Arc::from(downstream)
 136| }
