 138| // ============================================================================
 139| // 转换操作符：map, filter, filter_map, flat_map, scan
 140| // ============================================================================
 141| 
 142| impl<T, E> Observable<T, E>
 143| where
 144|     T: Send + Sync + 'static,
 145|     E: Send + Sync + Clone + 'static,
 146| {
 147|     pub fn map<U, F>(&self, mut mapper: F) -> Observable<U, E>
 148|     where U: Send + Sync + 'static, F: FnMut(T) -> U + Send + Sync + 'static,
 149|     {
 150|         let source_fn = self.subscribe_fn.clone();
 151|         let mapper = Arc::new(Mutex::new(move |v| mapper(v)));
 152|         Observable::<U, E>::new_impl(move |downstream| {
 153|             let shared = wrap_downstream(downstream);
 154|             let s_next = shared.clone();
 155|             let s_err = shared.clone();
 156|             let s_cmp = shared;
 157|             let m_clone = mapper.clone();
 158|             source_fn(Box::new(Callbacks {
 159|                 on_next: Mutex::new(Box::new(move |v| {
 160|                     let mapped = if let Ok(mut g) = m_clone.lock() { (g)(v) } else { return; };
 161|                     s_next.on_next(mapped);
 162|                 })),
 163|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 164|                 on_completed: Mutex::new(Box::new(move || s_cmp.on_completed())),
 165|             }));
 166|             Subscription::empty()
 167|         })
 168|     }
 169| 
 170|     pub fn filter<F>(&self, mut predicate: F) -> Observable<T, E>
 171|     where F: FnMut(&T) -> bool + Send + Sync + 'static,
 172|     {
 173|         let source_fn = self.subscribe_fn.clone();
 174|         let predicate = Arc::new(Mutex::new(move |v: &T| predicate(v)));
 175|         Observable::<T, E>::new_impl(move |downstream| {
 176|             let shared = wrap_downstream(downstream);
 177|             let s_next = shared.clone();
 178|             let s_err = shared.clone();
 179|             let s_cmp = shared;
 180|             let p_clone = predicate.clone();
 181|             source_fn(Box::new(Callbacks {
 182|                 on_next: Mutex::new(Box::new(move |v| {
 183|                     let ok = if let Ok(mut g) = p_clone.lock() { (g)(&v) } else { false };
 184|                     if ok { s_next.on_next(v); }
 185|                 })),
 186|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 187|                 on_completed: Mutex::new(Box::new(move || s_cmp.on_completed())),
 188|             }));
 189|             Subscription::empty()
 190|         })
 191|     }
 192| 
 193|     pub fn filter_map<U, F>(&self, mut f: F) -> Observable<U, E>
 194|     where U: Send + Sync + 'static, F: FnMut(T) -> Option<U> + Send + Sync + 'static,
 195|     {
 196|         let source_fn = self.subscribe_fn.clone();
 197|         let fm = Arc::new(Mutex::new(move |v| f(v)));
 198|         Observable::<U, E>::new_impl(move |downstream| {
 199|             let shared = wrap_downstream(downstream);
 200|             let s_next = shared.clone();
 201|             let s_err = shared.clone();
 202|             let s_cmp = shared;
 203|             let fm_clone = fm.clone();
 204|             source_fn(Box::new(Callbacks {
 205|                 on_next: Mutex::new(Box::new(move |v: T| {
 206|                     let opt = if let Ok(mut g) = fm_clone.lock() { (g)(v) } else { None };
 207|                     if let Some(u) = opt { s_next.on_next(u); }
 208|                 })),
 209|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 210|                 on_completed: Mutex::new(Box::new(move || s_cmp.on_completed())),
 211|             }));
 212|             Subscription::empty()
 213|         })
 214|     }
 215| 
 216|     pub fn flat_map<U, F>(&self, mut mapper: F) -> Observable<U, E>
 217|     where U: Send + Sync + 'static, F: FnMut(T) -> Observable<U, E> + Send + Sync + 'static,
 218|     {
 219|         let source_fn = self.subscribe_fn.clone();
 220|         let mapper = Arc::new(Mutex::new(move |v: T| mapper(v)));
 221|         Observable::<U, E>::new_impl(move |downstream| {
 222|             let shared = wrap_downstream(downstream);
 223|             let s_err = shared.clone();
 224|             let s_cmp = shared.clone();
 225|             let m_clone = mapper.clone();
 226|             let s_inner = shared.clone();
 227|             source_fn(Box::new(Callbacks {
 228|                 on_next: Mutex::new(Box::new(move |v: T| {
 229|                     let inner = if let Ok(mut g) = m_clone.lock() { (g)(v) } else { return; };
 230|                     let s1 = s_inner.clone();
 231|                     let s2 = s_inner.clone();
 232|                     inner.subscribe(Callbacks {
 233|                         on_next: Mutex::new(Box::new(move |u| s1.on_next(u))),
 234|                         on_error: Mutex::new(Box::new(move |e| s2.on_error(e))),
 235|                         on_completed: Mutex::new(Box::new(|| {})),
 236|                     });
 237|                 })),
 238|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 239|                 on_completed: Mutex::new(Box::new(move || s_cmp.on_completed())),
 240|             }));
 241|             Subscription::empty()
 242|         })
 243|     }
