 245|     pub fn scan<Acc, F>(&self, seed: Acc, mut scanner: F) -> Observable<Acc, E>
 246|     where Acc: Send + Sync + Clone + 'static, F: FnMut(Acc, T) -> Acc + Send + Sync + 'static,
 247|     {
 248|         let source_fn = self.subscribe_fn.clone();
 249|         let acc = Arc::new(Mutex::new(seed));
 250|         let scanner = Arc::new(Mutex::new(move |a: Acc, v: T| scanner(a, v)));
 251|         Observable::<Acc, E>::new_impl(move |downstream| {
 252|             let shared = wrap_downstream(downstream);
 253|             let s_next = shared.clone();
 254|             let s_err = shared.clone();
 255|             let s_cmp = shared;
 256|             let ac_next = acc.clone();
 257|             let ac_store = acc.clone();
 258|             let sc_clone = scanner.clone();
 259|             source_fn(Box::new(Callbacks {
 260|                 on_next: Mutex::new(Box::new(move |v| {
 261|                     let cur = if let Ok(g) = ac_next.lock() { g.clone() } else { return; };
 262|                     let next = if let Ok(mut g) = sc_clone.lock() { (g)(cur, v) } else { return; };
 263|                     if let Ok(mut g) = ac_store.lock() { *g = next.clone(); }
 264|                     s_next.on_next(next);
 265|                 })),
 266|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 267|                 on_completed: Mutex::new(Box::new(move || s_cmp.on_completed())),
 268|             }));
 269|             Subscription::empty()
 270|         })
 271|     }
 272| }
