 274| // ============================================================================
 275| // 过滤操作符：take, skip, first, last, take_while, skip_while
 276| // ============================================================================
 277| 
 278| impl<T, E> Observable<T, E>
 279| where
 280|     T: Send + Sync + 'static,
 281|     E: Send + Sync + Clone + 'static,
 282| {
 283|     pub fn take(&self, n: usize) -> Observable<T, E> {
 284|         let source_fn = self.subscribe_fn.clone();
 285|         Observable::<T, E>::new_impl(move |downstream| {
 286|             let shared = wrap_downstream(downstream);
 287|             let remaining = Arc::new(Mutex::new(n));
 288|             let stopped = Arc::new(Mutex::new(false));
 289|             let rem_next = remaining.clone();
 290|             let stop_next = stopped.clone();
 291|             let stop_cmp = stopped.clone();
 292|             let s_next = shared.clone();
 293|             let s_err = shared.clone();
 294|             let s_cmp = shared;
 295|             source_fn(Box::new(Callbacks {
 296|                 on_next: Mutex::new(Box::new(move |v| {
 297|                     // 已停止：彻底丢弃后续值
 298|                     if *stop_next.lock().unwrap() { return; }
 299|                     let mut guard = rem_next.lock().unwrap();
 300|                     if *guard > 0 {
 301|                         *guard -= 1;
 302|                         let should_complete = *guard == 0;
 303|                         drop(guard);
 304|                         s_next.on_next(v);
 305|                         if should_complete {
 306|                             *stop_next.lock().unwrap() = true;
 307|                             s_next.on_completed();
 308|                         }
 309|                     }
 310|                 })),
 311|                 on_error: Mutex::new(Box::new(move |e| {
 312|                     if *stopped.lock().unwrap() { return; }
 313|                     s_err.on_error(e);
 314|                 })),
 315|                 on_completed: Mutex::new(Box::new(move || {
 316|                     if *stop_cmp.lock().unwrap() { return; }
 317|                     s_cmp.on_completed();
 318|                 })),
 319|             }));
 320|             Subscription::empty()
 321|         })
 322|     }
 323| 
 324|     pub fn skip(&self, n: usize) -> Observable<T, E> {
 325|         let source_fn = self.subscribe_fn.clone();
 326|         let skipped = Arc::new(Mutex::new(0usize));
 327|         Observable::<T, E>::new_impl(move |downstream| {
 328|             let shared = wrap_downstream(downstream);
 329|             let s_next = shared.clone();
 330|             let s_err = shared.clone();
 331|             let s_cmp = shared;
 332|             let sk_next = skipped.clone();
 333|             source_fn(Box::new(Callbacks {
 334|                 on_next: Mutex::new(Box::new(move |v| {
 335|                     let mut guard = sk_next.lock().unwrap();
 336|                     if *guard < n {
 337|                         *guard += 1;
 338|                     } else {
 339|                         drop(guard);
 340|                         s_next.on_next(v);
 341|                     }
 342|                 })),
 343|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 344|                 on_completed: Mutex::new(Box::new(move || s_cmp.on_completed())),
 345|             }));
 346|             Subscription::empty()
 347|         })
 348|     }
 349| 
 350|     pub fn first(&self) -> Observable<T, E> { self.take(1) }
 351| 
 352|     pub fn last(&self) -> Observable<T, E> {
 353|         let source_fn = self.subscribe_fn.clone();
 354|         Observable::<T, E>::new_impl(move |downstream| {
 355|             let shared = wrap_downstream(downstream);
 356|             let s_next = shared.clone();
 357|             let s_err = shared.clone();
 358|             let s_cmp = shared;
 359|             let last_val: Arc<Mutex<Option<T>>> = Arc::new(Mutex::new(None));
 360|             let last_next = last_val.clone();
 361|             let last_cmp = last_val.clone();
 362|             source_fn(Box::new(Callbacks {
 363|                 on_next: Mutex::new(Box::new(move |v| { *last_next.lock().unwrap() = Some(v); })),
 364|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 365|                 on_completed: Mutex::new(Box::new(move || {
 366|                     let last = last_cmp.lock().unwrap().take();
 367|                     if let Some(v) = last { s_next.on_next(v); }
 368|                     s_cmp.on_completed();
 369|                 })),
 370|             }));
 371|             Subscription::empty()
 372|         })
 373|     }
 374| 
 375|     pub fn take_while<F>(&self, mut predicate: F) -> Observable<T, E>
 376|     where F: FnMut(&T) -> bool + Send + Sync + 'static,
 377|     {
 378|         let source_fn = self.subscribe_fn.clone();
 379|         let predicate = Arc::new(Mutex::new(move |v: &T| predicate(v)));
 380|         Observable::<T, E>::new_impl(move |downstream| {
 381|             let shared = wrap_downstream(downstream);
 382|             let s_next = shared.clone();
 383|             let s_err = shared.clone();
 384|             let s_cmp = shared;
 385|             let stopped = Arc::new(Mutex::new(false));
 386|             let stop_next = stopped.clone();
 387|             let p_clone = predicate.clone();
 388|             source_fn(Box::new(Callbacks {
 389|                 on_next: Mutex::new(Box::new(move |v| {
 390|                     if *stop_next.lock().unwrap() { return; }
 391|                     let ok = if let Ok(mut g) = p_clone.lock() { (g)(&v) } else { false };
 392|                     if ok {
 393|                         s_next.on_next(v);
 394|                     } else {
 395|                         *stop_next.lock().unwrap() = true;
 396|                         s_next.on_completed();
 397|                     }
 398|                 })),
 399|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 400|                 on_completed: Mutex::new(Box::new(move || s_cmp.on_completed())),
 401|             }));
 402|             Subscription::empty()
 403|         })
 404|     }
 405| 
 406|     pub fn skip_while<F>(&self, mut predicate: F) -> Observable<T, E>
 407|     where F: FnMut(&T) -> bool + Send + Sync + 'static,
 408|     {
 409|         let source_fn = self.subscribe_fn.clone();
 410|         let predicate = Arc::new(Mutex::new(move |v: &T| predicate(v)));
 411|         Observable::<T, E>::new_impl(move |downstream| {
 412|             let shared = wrap_downstream(downstream);
 413|             let s_next = shared.clone();
 414|             let s_err = shared.clone();
 415|             let s_cmp = shared;
 416|             let p_clone = predicate.clone();
 417|             let taken = Arc::new(Mutex::new(false));
 418|             let tk_next = taken.clone();
 419|             source_fn(Box::new(Callbacks {
 420|                 on_next: Mutex::new(Box::new(move |v| {
 421|                     let mut pass_guard = tk_next.lock().unwrap();
 422|                     if !*pass_guard {
 423|                         if let Ok(mut g) = p_clone.lock() { if (g)(&v) { return; } }
 424|                         *pass_guard = true;
 425|                     }
 426|                     drop(pass_guard);
 427|                     s_next.on_next(v);
 428|                 })),
 429|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 430|                 on_completed: Mutex::new(Box::new(move || s_cmp.on_completed())),
 431|             }));
 432|             Subscription::empty()
 433|         })
 434|     }
 435| }
