 437| // ============================================================================
 438| // 聚合操作符：count, reduce, sum, collect
 439| // ============================================================================
 440| 
 441| impl<T, E> Observable<T, E>
 442| where
 443|     T: Send + Sync + 'static,
 444|     E: Send + Sync + Clone + 'static,
 445| {
 446|     pub fn count(&self) -> Observable<usize, E> {
 447|         let source_fn = self.subscribe_fn.clone();
 448|         Observable::<usize, E>::new_impl(move |downstream| {
 449|             let shared = wrap_downstream(downstream);
 450|             let s_err = shared.clone();
 451|             let s_cmp = shared.clone();
 452|             let counter = Arc::new(Mutex::new(0usize));
 453|             let counter_next = counter.clone();
 454|             let counter_cmp = counter.clone();
 455|             source_fn(Box::new(Callbacks {
 456|                 on_next: Mutex::new(Box::new(move |_| { *counter_next.lock().unwrap() += 1; })),
 457|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 458|                 on_completed: Mutex::new(Box::new(move || {
 459|                     let n = *counter_cmp.lock().unwrap();
 460|                     shared.on_next(n);
 461|                     s_cmp.on_completed();
 462|                 })),
 463|             }));
 464|             Subscription::empty()
 465|         })
 466|     }
 467| 
 468|     pub fn reduce<Acc, F>(&self, seed: Acc, mut f: F) -> Observable<Acc, E>
 469|     where Acc: Send + Sync + Clone + 'static, F: FnMut(Acc, T) -> Acc + Send + Sync + 'static,
 470|     {
 471|         let source_fn = self.subscribe_fn.clone();
 472|         let acc = Arc::new(Mutex::new(seed));
 473|         let f = Arc::new(Mutex::new(move |a: Acc, v: T| f(a, v)));
 474|         Observable::<Acc, E>::new_impl(move |downstream| {
 475|             let shared = wrap_downstream(downstream);
 476|             let s_err = shared.clone();
 477|             let s_cmp = shared.clone();
 478|             let ac_next = acc.clone();
 479|             let ac_store = acc.clone();
 480|             let ac_cmp = acc.clone();
 481|             let f_clone = f.clone();
 482|             source_fn(Box::new(Callbacks {
 483|                 on_next: Mutex::new(Box::new(move |v| {
 484|                     let cur = if let Ok(g) = ac_next.lock() { g.clone() } else { return; };
 485|                     let next = if let Ok(mut g) = f_clone.lock() { (g)(cur, v) } else { return; };
 486|                     if let Ok(mut g) = ac_store.lock() { *g = next; }
 487|                 })),
 488|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 489|                 on_completed: Mutex::new(Box::new(move || {
 490|                     let result = if let Ok(g) = ac_cmp.lock() { g.clone() } else { return; };
 491|                     shared.on_next(result);
 492|                     s_cmp.on_completed();
 493|                 })),
 494|             }));
 495|             Subscription::empty()
 496|         })
 497|     }
 498| 
 499|     pub fn collect(&self) -> Observable<Vec<T>, E> {
 500|         let source_fn = self.subscribe_fn.clone();
 501|         Observable::<Vec<T>, E>::new_impl(move |downstream| {
 502|             let shared = wrap_downstream(downstream);
 503|             let s_err = shared.clone();
 504|             let s_cmp = shared.clone();
 505|             let buf: Arc<Mutex<Vec<T>>> = Arc::new(Mutex::new(Vec::new()));
 506|             let buf_next = buf.clone();
 507|             let buf_cmp = buf.clone();
 508|             source_fn(Box::new(Callbacks {
 509|                 on_next: Mutex::new(Box::new(move |v| buf_next.lock().unwrap().push(v))),
 510|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 511|                 on_completed: Mutex::new(Box::new(move || {
 512|                     let items = std::mem::take(&mut *buf_cmp.lock().unwrap());
 513|                     shared.on_next(items);
 514|                     s_cmp.on_completed();
 515|                 })),
 516|             }));
 517|             Subscription::empty()
 518|         })
 519|     }
 520| }
 521| 
 522| impl<T, E> Observable<T, E>
 523| where
 524|     T: Send + Sync + std::ops::Add<Output = T> + Default + Clone + 'static,
 525|     E: Send + Sync + Clone + 'static,
 526| {
 527|     pub fn sum(&self) -> Observable<T, E> { self.reduce(T::default(), |acc, v| acc + v) }
 528| }
