 684| impl<T, E> Observable<T, E>
 685| where
 686|     T: Send + Sync + 'static,
 687|     E: Send + Sync + Clone + Default + 'static,
 688| {
 689|     /// 取第 N 个值（从 0 开始），越界发出错误。  
 690|     /// 文档见 [`crate::operators::filter::element_at`]
 691|     pub fn element_at(self, index: usize) -> Observable<T, E> {
 692|         let source_fn = self.subscribe_fn.clone();
 693|         Observable::<T, E>::new_impl(move |downstream| {
 694|             let shared: Arc<dyn Observer<T, E>> = Arc::from(downstream);
 695|             let pos: Arc<Mutex<usize>> = Arc::new(Mutex::new(0));
 696|             let s_next = shared.clone();
 697|             let s_err = shared.clone();
 698|             let s_cmp = shared.clone();
 699|             let pos_next = pos.clone();
 700|             source_fn(Box::new(Callbacks {
 701|                 on_next: Mutex::new(Box::new(move |v: T| {
 702|                     let mut guard = pos_next.lock().unwrap();
 703|                     if *guard == index {
 704|                         *guard += 1;
 705|                         drop(guard);
 706|                         s_next.on_next(v);
 707|                         s_next.on_completed();
 708|                     } else {
 709|                         *guard += 1;
 710|                     }
 711|                 })),
 712|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 713|                 on_completed: Mutex::new(Box::new(move || {
 714|                     s_cmp.on_error(E::default());
 715|                 })),
 716|             }));
 717|             Subscription::empty()
 718|         })
 719|     }
 720| }
