 722| impl<T, E> Observable<T, E>
 723| where
 724|     T: Clone + Send + Sync + 'static,
 725|     E: Send + Sync + Clone + 'static,
 726| {
 727|     /// 如果流在 completed 前没有发射任何值，发出默认值。  
 728|     /// 文档见 [`crate::operators::utility::default_if_empty`]
 729|     pub fn default_if_empty(self, default_value: T) -> Observable<T, E> {
 730|         let source_fn = self.subscribe_fn.clone();
 731|         let default = Arc::new(default_value);
 732|         Observable::<T, E>::new_impl(move |downstream| {
 733|             let shared: Arc<dyn Observer<T, E>> = Arc::from(downstream);
 734|             let emitted: Arc<Mutex<bool>> = Arc::new(Mutex::new(false));
 735|             let s_next = shared.clone();
 736|             let s_err = shared.clone();
 737|             let s_cmp = shared.clone();
 738|             let em_next = emitted.clone();
 739|             let def_clone = default.clone();
 740|             let s_cmp_next = s_next.clone();
 741|             source_fn(Box::new(Callbacks {
 742|                 on_next: Mutex::new(Box::new(move |v: T| {
 743|                     *em_next.lock().unwrap() = true;
 744|                     s_next.on_next(v);
 745|                 })),
 746|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 747|                 on_completed: Mutex::new(Box::new(move || {
 748|                     if !*emitted.lock().unwrap() {
 749|                         s_cmp_next.on_next((*def_clone).clone());
 750|                     }
 751|                     s_cmp.on_completed();
 752|                 })),
 753|             }));
 754|             Subscription::empty()
 755|         })
 756|     }
