 758|     /// 忽略所有 on_next，只透传 completed 和 error。  
 759|     /// 文档见 [`crate::operators::utility::ignore_elements`]
 760|     pub fn ignore_elements(self) -> Observable<T, E> {
 761|         let source_fn = self.subscribe_fn.clone();
 762|         Observable::<T, E>::new_impl(move |downstream| {
 763|             let shared: Arc<dyn Observer<T, E>> = Arc::from(downstream);
 764|             let s_err = shared.clone();
 765|             let s_cmp = shared;
 766|             source_fn(Box::new(Callbacks {
 767|                 on_next: Mutex::new(Box::new(|_| {})),
 768|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 769|                 on_completed: Mutex::new(Box::new(move || s_cmp.on_completed())),
 770|             }));
 771|             Subscription::empty()
 772|         })
 773|     }
