 775|     /// 将整个流收集为 Vec<T>，结束时一次发出。  
 776|     /// 文档见 [`crate::operators::utility::to_list`]
 777|     pub fn to_list(self) -> Observable<Vec<T>, E> {
 778|         self.collect()
 779|     }
