 781|     /// 透传上游值，同时执行副作用（不修改流）。  
 782|     /// 文档见 [`crate::operators::utility::tap`]
 783|     pub fn tap<F>(self, mut on_next_fn: F) -> Observable<T, E>
 784|     where F: FnMut(&T) + Send + Sync + 'static,
 785|     {
 786|         let source_fn = self.subscribe_fn.clone();
 787|         let tap_fn = Arc::new(Mutex::new(move |v: &T| on_next_fn(v)));
 788|         Observable::<T, E>::new_impl(move |downstream| {
 789|             let shared: Arc<dyn Observer<T, E>> = Arc::from(downstream);
 790|             let s_next = shared.clone();
 791|             let s_err = shared.clone();
 792|             let s_cmp = shared.clone();
 793|             let tap_clone = tap_fn.clone();
 794|             source_fn(Box::new(Callbacks {
 795|                 on_next: Mutex::new(Box::new(move |v: T| {
 796|                     if let Ok(mut f) = tap_clone.lock() { f(&v); }
 797|                     s_next.on_next(v);
 798|                 })),
 799|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 800|                 on_completed: Mutex::new(Box::new(move || s_cmp.on_completed())),
 801|             }));
 802|             Subscription::empty()
 803|         })
 804|     }
