 806|     /// 给每个值附加发射时间戳（毫秒）。  
 807|     /// 文档见 [`crate::operators::utility::timestamp`]
 808|     pub fn timestamp(self) -> Observable<(T, u64), E> {
 809|         let source_fn = self.subscribe_fn.clone();
 810|         Observable::<(T, u64), E>::new_impl(move |downstream| {
 811|             let shared: Arc<dyn Observer<(T, u64), E>> = Arc::from(downstream);
 812|             let s_next = shared.clone();
 813|             let s_err = shared.clone();
 814|             let s_cmp = shared;
 815|             source_fn(Box::new(Callbacks {
 816|                 on_next: Mutex::new(Box::new(move |v: T| {
 817|                     let ts = std::time::SystemTime::now()
 818|                         .duration_since(std::time::UNIX_EPOCH)
 819|                         .map(|d| d.as_millis() as u64)
 820|                         .unwrap_or(0);
 821|                     s_next.on_next((v, ts));
 822|                 })),
 823|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 824|                 on_completed: Mutex::new(Box::new(move || s_cmp.on_completed())),
 825|             }));
 826|             Subscription::empty()
 827|         })
 828|     }
 829| }
