 858| impl<T, E> Observable<T, E>
 859| where
 860|     T: Send + Sync + 'static,
 861|     E: Send + Sync + Clone + 'static,
 862| {
 863|     /// 将每个值映射为 Observable，按顺序拼接。  
 864|     /// 文档见 [`crate::operators::transform::concat_map`]
 865|     pub fn concat_map<U, F>(self, mut mapper: F) -> Observable<U, E>
 866|     where
 867|         U: Send + Sync + 'static,
 868|         F: FnMut(T) -> Observable<U, E> + Send + Sync + 'static,
 869|     {
 870|         let source_fn = self.subscribe_fn.clone();
 871|         let mapper = Arc::new(Mutex::new(move |v: T| mapper(v)));
 872|         Observable::<U, E>::new_impl(move |downstream| {
 873|             let shared: Arc<dyn Observer<U, E>> = Arc::from(downstream);
 874|             let s_err = shared.clone();
 875|             let s_cmp = shared.clone();
 876|             let m_clone = mapper.clone();
 877|             let s_inner = shared.clone();
 878|             let inner_done: Arc<Mutex<bool>> = Arc::new(Mutex::new(true));
 879|             let ic_next = inner_done.clone();
 880|             source_fn(Box::new(Callbacks {
 881|                 on_next: Mutex::new(Box::new(move |v: T| {
 882|                     let inner = if let Ok(mut g) = m_clone.lock() { (g)(v) } else { return; };
 883|                     *ic_next.lock().unwrap() = false;
 884|                     let s1 = s_inner.clone();
 885|                     let s2 = s_inner.clone();
 886|                     let ic2 = ic_next.clone();
 887|                     inner.subscribe(Callbacks {
 888|                         on_next: Mutex::new(Box::new(move |u| s1.on_next(u))),
 889|                         on_error: Mutex::new(Box::new(move |e| s2.on_error(e))),
 890|                         on_completed: Mutex::new(Box::new(move || { *ic2.lock().unwrap() = true; })),
 891|                     });
 892|                 })),
 893|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 894|                 on_completed: Mutex::new(Box::new(move || {
 895|                     loop {
 896|                         if *inner_done.lock().unwrap() { break; }
 897|                         std::thread::sleep(std::time::Duration::from_micros(1));
 898|                     }
 899|                     s_cmp.on_completed();
 900|                 })),
 901|             }));
 902|             Subscription::empty()
 903|         })
 904|     }
