   7| // ============================================================================
   8| // Observable —— 可观察对象
   9| // ============================================================================
  10| 
  11| pub struct Observable<T, E = ()> {
  12|     pub(crate) subscribe_fn: Arc<dyn Fn(Box<dyn Observer<T, E>>) -> Subscription + Send + Sync>,
  13| }
  14| 
  15| impl<T, E> Clone for Observable<T, E> {
  16|     fn clone(&self) -> Self { Self { subscribe_fn: self.subscribe_fn.clone() } }
  17| }
