  19| // ============================================================================
  20| // Callbacks —— 用三个闭包实现 Observer
  21| // ============================================================================
  22| 
  23| pub struct Callbacks<T, E> {
  24|     pub on_next: Mutex<Box<dyn FnMut(T) + Send + Sync>>,
  25|     pub on_error: Mutex<Box<dyn FnMut(E) + Send + Sync>>,
  26|     pub on_completed: Mutex<Box<dyn FnMut() + Send + Sync>>,
  27| }
  28| 
  29| impl<T, E> Observer<T, E> for Callbacks<T, E> {
  30|     fn on_next(&self, value: T) { if let Ok(mut f) = self.on_next.lock() { (f)(value); } }
  31|     fn on_error(&self, err: E) { if let Ok(mut f) = self.on_error.lock() { (f)(err); } }
  32|     fn on_completed(&self) { if let Ok(mut f) = self.on_completed.lock() { (f)(); } }
  33| }
