  39| impl<T, E> Observable<T, E>
  40| where
  41|     T: Send + Sync + 'static,
  42|     E: Send + Sync + 'static,
  43| {
  44|     pub(crate) fn new_impl<F>(f: F) -> Self
  45|     where F: Fn(Box<dyn Observer<T, E>>) -> Subscription + Send + Sync + 'static,
  46|     { Self { subscribe_fn: Arc::new(f) } }
  47| 
  48|     pub fn subscribe<O>(&self, observer: O) -> Subscription
  49|     where O: Observer<T, E> + 'static,
  50|     { (self.subscribe_fn)(Box::new(observer)) }
  51| 
  52|     pub fn subscribe_on_next<F>(&self, on_next: F) -> Subscription
  53|     where F: FnMut(T) + Send + Sync + 'static,
  54|     {
  55|         self.subscribe(Callbacks {
  56|             on_next: Mutex::new(Box::new(on_next)),
  57|             on_error: Mutex::new(Box::new(|_| {})),
  58|             on_completed: Mutex::new(Box::new(|| {})),
  59|         })
  60|     }
