 245|     pub fn scan<Acc, F>(&self, seed: Acc, mut scanner: F) -> Observable<Acc, E>
 246|     where Acc: Send + Sync + Clone + 'static, F: FnMut(Acc, T) -> Acc + Send + Sync + 'static,
 247|     {
 248|         let source_fn = self.subscribe_fn.clone();
