 251|         Observable::<Acc, E>::new_impl(move |downstream| {
 252|             let shared = wrap_downstream(downstream);
 253|             let s_next = shared.clone();
 254|             let s_err = shared.clone();
 255|             let s_cmp = shared;
 256|             let ac_next = acc.clone();
 257|             let ac_store = acc.clone();
 258|             let sc_clone = scanner.clone();
 259|             source_fn(Box::new(Callbacks {
 260|                 on_next: Mutex::new(Box::new(move |v| {
 261|                     let cur = if let Ok(g) = ac_next.lock() { g.clone() } else { return; };
 262|                     let next = if let Ok(mut g) = sc_clone.lock() { (g)(cur, v) } else { return; };
