 406|     pub fn skip_while<F>(&self, mut predicate: F) -> Observable<T, E>
 407|     where F: FnMut(&T) -> bool + Send + Sync + 'static,
 408|     {
 409|         let source_fn = self.subscribe_fn.clone();
 410|         let predicate = Arc::new(Mutex::new(move |v: &T| predicate(v)));
 411|         Observable::<T, E>::new_impl(move |downstream| {
 412|             let shared = wrap_downstream(downstream);
 413|             let s_next = shared.clone();
 414|             let s_err = shared.clone();
 415|             let s_cmp = shared;
 416|             let p_clone = predicate.clone();
 417|             let taken = Arc::new(Mutex::new(false));
 418|             let tk_next = taken.clone();
 419|             source_fn(Box::new(Callbacks {
 420|                 on_next: Mutex::new(Box::new(move |v| {
 421|                     let mut pass_guard = tk_next.lock().unwrap();
 422|                     if !*pass_guard {
 423|                         if let Ok(mut g) = p_clone.lock() { if (g)(&v) { return; } }
 424|                         *pass_guard = true;
 425|                     }
 426|                     drop(pass_guard);
 427|                     s_next.on_next(v);
 428|                 })),
 429|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 430|                 on_completed: Mutex::new(Box::new(move || s_cmp.on_completed())),
 431|             }));
 432|             Subscription::empty()
 433|         })
 434|     }
