 449|             let shared = wrap_downstream(downstream);
 450|             let s_err = shared.clone();
 451|             let s_cmp = shared.clone();
 452|             let counter = Arc::new(Mutex::new(0usize));
 453|             let counter_next = counter.clone();
 454|             let counter_cmp = counter.clone();
 455|             source_fn(Box::new(Callbacks {
 456|                 on_next: Mutex::new(Box::new(move |_| { *counter_next.lock().unwrap() += 1; })),
 457|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 458|                 on_completed: Mutex::new(Box::new(move || {
 459|                     let n = *counter_cmp.lock().unwrap();
