 468|     pub fn reduce<Acc, F>(&self, seed: Acc, mut f: F) -> Observable<Acc, E>
 469|     where Acc: Send + Sync + Clone + 'static, F: FnMut(Acc, T) -> Acc + Send + Sync + 'static,
 470|     {
 471|         let source_fn = self.subscribe_fn.clone();
 472|         let acc = Arc::new(Mutex::new(seed));
 473|         let f = Arc::new(Mutex::new(move |a: Acc, v: T| f(a, v)));
 474|         Observable::<Acc, E>::new_impl(move |downstream| {
 475|             let shared = wrap_downstream(downstream);
 476|             let s_err = shared.clone();
 477|             let s_cmp = shared.clone();
 478|             let ac_next = acc.clone();
 479|             let ac_store = acc.clone();
 480|             let ac_cmp = acc.clone();
 481|             let f_clone = f.clone();
 482|             source_fn(Box::new(Callbacks {
 483|                 on_next: Mutex::new(Box::new(move |v| {
 484|                     let cur = if let Ok(g) = ac_next.lock() { g.clone() } else { return; };
 485|                     let next = if let Ok(mut g) = f_clone.lock() { (g)(cur, v) } else { return; };
 486|                     if let Ok(mut g) = ac_store.lock() { *g = next; }
 487|                 })),
 488|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 489|                 on_completed: Mutex::new(Box::new(move || {
 490|                     let result = if let Ok(g) = ac_cmp.lock() { g.clone() } else { return; };
 491|                     shared.on_next(result);
 492|                     s_cmp.on_completed();
 493|                 })),
 494|             }));
 495|             Subscription::empty()
