 533| 
 534| impl<T, E> Observable<T, E>
 535| where
 536|     T: Send + Sync + Clone + 'static,
 537|     E: Send + Sync + Clone + 'static,
 538| {
 539|     pub fn start_with<I>(&self, prefix: I) -> Observable<T, E>
 540|     where I: IntoIterator<Item = T>, I::IntoIter: Send + Sync + 'static,
 541|     {
 542|         let prefix: Vec<T> = prefix.into_iter().collect();
 543|         let source_fn = self.subscribe_fn.clone();
 544|         Observable::<T, E>::new_impl(move |downstream| {
 545|             let shared = wrap_downstream(downstream);
 546|             for v in &prefix { shared.on_next(v.clone()); }
 547|             let s_next = shared.clone();
 548|             let s_err = shared.clone();
 549|             let s_cmp = shared;
 550|             source_fn(Box::new(Callbacks {
 551|                 on_next: Mutex::new(Box::new(move |v| s_next.on_next(v))),
 552|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 553|                 on_completed: Mutex::new(Box::new(move || s_cmp.on_completed())),
 554|             }));
 555|             Subscription::empty()
 556|         })
 557|     }
 558| 
 559|     pub fn concat(&self, other: Observable<T, E>) -> Observable<T, E> {
 560|         let source_fn = self.subscribe_fn.clone();
 561|         let other_fn = other.subscribe_fn.clone();
 562|         Observable::<T, E>::new_impl(move |downstream| {
 563|             let shared = wrap_downstream(downstream);
 564|             let s_err = shared.clone();
 565|             let s_cmp_src = shared.clone();
 566|             let other_fn_clone = other_fn.clone();
 567|             source_fn(Box::new(Callbacks {
 568|                 on_next: Mutex::new(Box::new(move |v| shared.on_next(v))),
 569|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 570|                 on_completed: Mutex::new(Box::new(move || {
 571|                     let s1 = s_cmp_src.clone();
 572|                     let s2 = s_cmp_src.clone();
 573|                     let s3 = s_cmp_src.clone();
 574|                     other_fn_clone(Box::new(Callbacks {
 575|                         on_next: Mutex::new(Box::new(move |v| s1.on_next(v))),
 576|                         on_error: Mutex::new(Box::new(move |e| s2.on_error(e))),
 577|                         on_completed: Mutex::new(Box::new(move || s3.on_completed())),
 578|                     }));
 579|                 })),
 580|             }));
 581|             Subscription::empty()
 582|         })
 583|     }
 584| }
