 590| impl<T, E> Observable<T, E>
 591| where
 592|     T: Clone + Eq + Hash + Send + Sync + 'static,
 593|     E: Send + Sync + Clone + 'static,
 594| {
 595|     /// 去重，丢弃已见过的值。  
 596|     /// 文档见 [`crate::operators::filter::distinct`]
 597|     pub fn distinct(self) -> Observable<T, E> {
 598|         let source_fn = self.subscribe_fn.clone();
 599|         Observable::<T, E>::new_impl(move |downstream| {
 600|             let shared: Arc<dyn Observer<T, E>> = Arc::from(downstream);
 601|             let seen: Arc<Mutex<HashSet<T>>> = Arc::new(Mutex::new(HashSet::new()));
 602|             let s_next = shared.clone();
 603|             let s_err = shared.clone();
 604|             let s_cmp = shared.clone();
 605|             let seen_next = seen.clone();
 606|             source_fn(Box::new(Callbacks {
 607|                 on_next: Mutex::new(Box::new(move |v: T| {
 608|                     let mut guard = seen_next.lock().unwrap();
 609|                     if guard.insert(v.clone()) {
 610|                         drop(guard);
 611|                         s_next.on_next(v);
 612|                     }
 613|                 })),
 614|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 615|                 on_completed: Mutex::new(Box::new(move || s_cmp.on_completed())),
 616|             }));
 617|             Subscription::empty()
 618|         })
 619|     }
 620| 
 621|     /// 去重（按 key 函数）。  
 622|     /// 文档见 [`crate::operators::filter::distinct_by`]
 623|     pub fn distinct_by<U, F>(self, key_fn: F) -> Observable<T, E>
 624|     where
 625|         U: Clone + Eq + Hash + Send + Sync + 'static,
 626|         F: Fn(&T) -> U + Send + Sync + 'static,
 627|     {
 628|         let source_fn = self.subscribe_fn.clone();
 629|         let key_fn = Arc::new(Mutex::new(key_fn));
 630|         Observable::<T, E>::new_impl(move |downstream| {
 631|             let shared: Arc<dyn Observer<T, E>> = Arc::from(downstream);
 632|             let seen: Arc<Mutex<HashSet<U>>> = Arc::new(Mutex::new(HashSet::new()));
 633|             let s_next = shared.clone();
 634|             let s_err = shared.clone();
 635|             let s_cmp = shared.clone();
 636|             let seen_next = seen.clone();
 637|             let key_clone = key_fn.clone();
 638|             source_fn(Box::new(Callbacks {
 639|                 on_next: Mutex::new(Box::new(move |v: T| {
 640|                     let key = if let Ok(g) = key_clone.lock() { (g)(&v) } else { return; };
 641|                     let mut guard = seen_next.lock().unwrap();
 642|                     if guard.insert(key) {
 643|                         drop(guard);
 644|                         s_next.on_next(v);
 645|                     }
 646|                 })),
 647|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 648|                 on_completed: Mutex::new(Box::new(move || s_cmp.on_completed())),
 649|             }));
 650|             Subscription::empty()
 651|         })
 652|     }
 653| 
 654|     /// 只丢弃连续重复的值。  
 655|     /// 文档见 [`crate::operators::filter::distinct_until_changed`]
 656|     pub fn distinct_until_changed(self) -> Observable<T, E> {
 657|         let source_fn = self.subscribe_fn.clone();
 658|         Observable::<T, E>::new_impl(move |downstream| {
 659|             let shared: Arc<dyn Observer<T, E>> = Arc::from(downstream);
 660|             let last: Arc<Mutex<Option<T>>> = Arc::new(Mutex::new(None));
 661|             let s_next = shared.clone();
 662|             let s_err = shared.clone();
 663|             let s_cmp = shared.clone();
 664|             let last_next = last.clone();
 665|             source_fn(Box::new(Callbacks {
 666|                 on_next: Mutex::new(Box::new(move |v: T| {
 667|                     let mut guard = last_next.lock().unwrap();
 668|                     match &*guard {
 669|                         Some(prev) if *prev == v => return,
 670|                         _ => {}
 671|                     }
 672|                     *guard = Some(v.clone());
 673|                     drop(guard);
 674|                     s_next.on_next(v);
 675|                 })),
 676|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 677|                 on_completed: Mutex::new(Box::new(move || s_cmp.on_completed())),
 678|             }));
 679|             Subscription::empty()
 680|         })
 681|     }
 682| }
