 910|         U: Send + Sync + 'static,
 911|         F: FnMut(T) -> Observable<U, E> + Send + Sync + 'static,
 912|     {
 913|         let source_fn = self.subscribe_fn.clone();
 914|         let mapper = Arc::new(Mutex::new(move |v: T| mapper(v)));
