 967|         let triggered_next = triggered.clone();
 968|         trigger.subscribe(Callbacks {
 969|             on_next: Mutex::new(Box::new(move |_| { *triggered_next.lock().unwrap() = true; })),
 970|             on_error: Mutex::new(Box::new(|_| {})),
 971|             on_completed: Mutex::new(Box::new(|| {})),
 972|         });
 973|         Observable::<T, E>::new_impl(move |downstream| {
 974|             let shared: Arc<dyn Observer<T, E>> = Arc::from(downstream);
 975|             let s_next = shared.clone();
 976|             let s_err = shared.clone();
 977|             let s_cmp = shared.clone();
 978|             let t_next = triggered.clone();
 979|             source_fn(Box::new(Callbacks {
 980|                 on_next: Mutex::new(Box::new(move |v: T| {
 981|                     if *t_next.lock().unwrap() {
 982|                         s_next.on_next(v);
 983|                     }
 984|                 })),
 985|                 on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 986|                 on_completed: Mutex::new(Box::new(move || s_cmp.on_completed())),
 987|             }));
 988|             Subscription::empty()
 989|         })
 990|     }
 991| 
 992|     /// 发射，直到另一个 Observable 发射就立即终止。  
 993|     /// 文档见 [`crate::operators::filter::take_until`]
 994|     pub fn take_until(self, trigger: &Observable<(), E>) -> Observable<T, E>
 995|     where E: Clone + Send + Sync + 'static,
 996|     {
 997|         let source_fn = self.subscribe_fn.clone();
 998|         let stopped: Arc<Mutex<bool>> = Arc::new(Mutex::new(false));
 999|         let stopped_t = stopped.clone();
1000|         let stopped_s = stopped.clone();
1001|         let stopped_next = stopped.clone();
1002|         trigger.subscribe(Callbacks {
1003|             on_next: Mutex::new(Box::new(move |_| {
1004|                 if !*stopped_t.lock().unwrap() { *stopped_t.lock().unwrap() = true; }
1005|             })),
1006|             on_error: Mutex::new(Box::new(move |_: E| {
1007|                 if !*stopped_s.lock().unwrap() { *stopped_s.lock().unwrap() = true; }
1008|             })),
1009|             on_completed: Mutex::new(Box::new(|| {})),
1010|         });
1011|         Observable::<T, E>::new_impl(move |downstream| {
1012|             let shared: Arc<dyn Observer<T, E>> = Arc::from(downstream);
1013|             let s_next = shared.clone();
1014|             let s_err = shared.clone();
1015|             let s_cmp = shared.clone();
1016|             let st_next = stopped_next.clone();
1017|             let st_err = stopped_next.clone();
1018|             let st_cmp = stopped_next.clone();
1019|             source_fn(Box::new(Callbacks {
1020|                 on_next: Mutex::new(Box::new(move |v: T| {
1021|                     if *st_next.lock().unwrap() { return; }
1022|                     s_next.on_next(v);
1023|                 })),
1024|                 on_error: Mutex::new(Box::new(move |e| {
1025|                     if *st_err.lock().unwrap() { return; }
1026|                     s_err.on_error(e);
1027|                 })),
1028|                 on_completed: Mutex::new(Box::new(move || {
1029|                     if *st_cmp.lock().unwrap() { return; }
1030|                     s_cmp.on_completed();
1031|                 })),
1032|             }));
1033|             Subscription::empty()
1034|         })
1035|     }
1036| }
