  1| //! 过滤操作符 —— 决定哪些数据通过，哪些被丢弃。
  2| //!
  3| //! | 操作符 | 说明 |
  4| //! |--------|------|
  5| //! | [`distinct`] | 去重，丢弃已见过的值 |
  6| //! | [`element_at`] | 只取第 N 个值（从 0 开始） |
  7| //! | [`skip_until`] | 跳过，直到另一个 Observable 发射才放行 |
  8| //! | [`take_until`] | 发射，直到另一个 Observable 发射就终止 |
  9| //! | [`distinct_until_changed`] | 只丢弃连续重复的值 |
 10| //!
 11| //! # 示例
 12| //!
 13| //! ```
 14| //! use rx_rust::prelude::*;
 15| //!
 16| //! // distinct：去重
 17| //! let result = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
 18| //! let r = result.clone();
 19| //! Observable::<i32, ()>::from_iter(vec![1, 2, 2, 3, 1, 4])
 20| //!     .distinct()
 21| //!     .subscribe_on_next(move |x| r.lock().unwrap().push(x));
 22| //! assert_eq!(*result.lock().unwrap(), vec![1, 2, 3, 4]);
 23| //!
 24| //! // element_at：取第 2 个
 25| //! let result = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
 26| //! let r = result.clone();
 27| //! Observable::<i32, ()>::from_iter(vec![10, 20, 30, 40])
 28| //!     .element_at(2)
 29| //!     .subscribe_on_next(move |x| r.lock().unwrap().push(x));
 30| //! assert_eq!(*result.lock().unwrap(), vec![30]);
 31| //! ```
 32| 
 33| use std::collections::HashSet;
 34| use std::hash::Hash;
 35| use std::sync::{Arc, Mutex};
 36| 
 37| use crate::observer::Observer;
 38| use crate::observable::Callbacks;
 39| use crate::subscription::Subscription;
 40| 
 41| /// 去重 —— 丢弃流中已经发射过的值。
 42| ///
 43| /// 只有**第一次出现**的值会被放行，后续重复的值全部丢弃。
 44| ///
 45| /// ## 备注
 46| /// - 使用 `HashSet` 存储已见过的值，需 `T: Eq + Hash`
 47| /// - 对大数据量或大对象，谨慎使用（内存占用）
 48| ///
 49| /// ## RxJS 对应
 50| /// [distinct](https://rxjs.dev/api/operators/distinct)
 51| pub fn distinct<T, E>(source: &crate::Observable<T, E>) -> crate::Observable<T, E>
 52| where
 53|     T: Clone + Eq + Hash + Send + Sync + 'static,
 54|     E: Send + Sync + Clone + 'static,
 55| {
 56|     let source_fn = source.subscribe_fn.clone();
 57|     crate::Observable::<T, E>::new_impl(move |downstream| {
 58|         let shared: Arc<dyn Observer<T, E>> = Arc::from(downstream);
 59|         let seen: Arc<Mutex<HashSet<T>>> = Arc::new(Mutex::new(HashSet::new()));
 60|         let s_next = shared.clone();
 61|         let s_err = shared.clone();
 62|         let s_cmp = shared.clone();
 63|         let seen_next = seen.clone();
 64|         source_fn(Box::new(Callbacks {
 65|             on_next: Mutex::new(Box::new(move |v: T| {
 66|                 let mut guard = seen_next.lock().unwrap();
 67|                 if guard.insert(v.clone()) {
 68|                     drop(guard);
 69|                     s_next.on_next(v);
 70|                 }
 71|             })),
 72|             on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
 73|             on_completed: Mutex::new(Box::new(move || s_cmp.on_completed())),
 74|         }));
 75|         Subscription::empty()
 76|     })
 77| }
 78| 
 79| /// 去重（按 key） —— 丢弃流中 key 已出现过的值。
 80| ///
 81| /// 与 [`distinct`] 类似，但先去重 `key_fn(v)`，再丢弃重复 key。
 82| ///
 83| /// ## RxJS 对应
 84| /// [distinct with keySelector](https://rxjs.dev/api/operators/distinct)
 85| pub fn distinct_by<T, U, E>(source: &crate::Observable<T, E>, key_fn: impl Fn(&T) -> U + Send + Sync + 'static) -> crate::Observable<T, E>
 86| where
 87|     T: Clone + Send + Sync + 'static,
 88|     U: Clone + Eq + Hash + Send + Sync + 'static,
 89|     E: Send + Sync + Clone + 'static,
 90| {
 91|     let source_fn = source.subscribe_fn.clone();
 92|     let key_fn = Arc::new(Mutex::new(key_fn));
 93|     crate::Observable::<T, E>::new_impl(move |downstream| {
 94|         let shared: Arc<dyn Observer<T, E>> = Arc::from(downstream);
 95|         let seen: Arc<Mutex<HashSet<U>>> = Arc::new(Mutex::new(HashSet::new()));
 96|         let s_next = shared.clone();
 97|         let s_err = shared.clone();
 98|         let s_cmp = shared.clone();
 99|         let seen_next = seen.clone();
100|         let key_clone = key_fn.clone();
101|         source_fn(Box::new(Callbacks {
102|             on_next: Mutex::new(Box::new(move |v: T| {
103|                 let key = if let Ok(g) = key_clone.lock() { (g)(&v) } else { return; };
104|                 let mut guard = seen_next.lock().unwrap();
105|                 if guard.insert(key) {
106|                     drop(guard);
107|                     s_next.on_next(v);
108|                 }
109|             })),
110|             on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
111|             on_completed: Mutex::new(Box::new(move || s_cmp.on_completed())),
112|         }));
113|         Subscription::empty()
114|     })
115| }
116| 
117| /// 取第 N 个值（从 0 开始），越界则发出错误。
118| ///
119| /// `index == 0` 取第一个，`index == 1` 取第二个，以此类推。
120| /// 如果流在第 N 个值之前完成，则发出 `OnError(E)`。
121| ///
122| /// ## RxJS 对应
123| /// [elementAt](https://rxjs.dev/api/operators/elementAt)
124| pub fn element_at<T, E>(source: &crate::Observable<T, E>, index: usize) -> crate::Observable<T, E>
125| where
126|     T: Send + Sync + 'static,
127|     E: Send + Sync + Clone + Default + 'static,
128| {
129|     let source_fn = source.subscribe_fn.clone();
130|     crate::Observable::<T, E>::new_impl(move |downstream| {
131|         let shared: Arc<dyn Observer<T, E>> = Arc::from(downstream);
132|         let pos: Arc<Mutex<usize>> = Arc::new(Mutex::new(0));
133|         let s_next = shared.clone();
134|         let s_err = shared.clone();
135|         let s_cmp = shared.clone();
136|         let pos_next = pos.clone();
137|         source_fn(Box::new(Callbacks {
138|             on_next: Mutex::new(Box::new(move |v: T| {
139|                 let mut guard = pos_next.lock().unwrap();
140|                 if *guard == index {
141|                     *guard += 1;
142|                     drop(guard);
143|                     s_next.on_next(v);
144|                     s_next.on_completed();
145|                 } else {
146|                     *guard += 1;
147|                 }
148|             })),
149|             on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
150|             on_completed: Mutex::new(Box::new(move || {
151|                 // 流结束时尚未到达 index，发出错误
152|                 s_cmp.on_error(E::default());
153|             })),
154|         }));
155|         Subscription::empty()
156|     })
157| }
158| 
159| /// 跳过，直到另一个 Observable 发射才放行。
160| ///
161| /// 上游值在 `trigger` 发射之前全部丢弃，触发后恢复正常透传。
162| ///
163| /// ## 备注
164| /// - 当前实现**不**等待 trigger 完成，仅跟踪触发状态
165| /// - trigger 完成或出错时不影响上游继续
166| ///
167| /// ## RxJS 对应
168| /// [skipUntil](https://rxjs.dev/api/operators/skipUntil)
169| pub fn skip_until<T, E>(source: &crate::Observable<T, E>, trigger: &crate::Observable<(), E>) -> crate::Observable<T, E>
170| where
171|     E: Clone + Default + Send + Sync + 'static,
172|     T: Send + Sync + 'static,
173| {
174|     let source_fn = source.subscribe_fn.clone();
175|     let triggered: Arc<Mutex<bool>> = Arc::new(Mutex::new(false));
176|     let triggered_next = triggered.clone();
177|     // 订阅 trigger，触发后设置标志
178|     trigger.subscribe(crate::observable::Callbacks {
179|         on_next: Mutex::new(Box::new(move |_| { *triggered_next.lock().unwrap() = true; })),
180|         on_error: Mutex::new(Box::new(|_| {})),
181|         on_completed: Mutex::new(Box::new(|| {})),
182|     });
183|     crate::Observable::<T, E>::new_impl(move |downstream| {
184|         let shared: Arc<dyn Observer<T, E>> = Arc::from(downstream);
185|         let s_next = shared.clone();
186|         let s_err = shared.clone();
187|         let s_cmp = shared.clone();
188|         let t_next = triggered.clone();
189|         source_fn(Box::new(Callbacks {
190|             on_next: Mutex::new(Box::new(move |v: T| {
191|                 if *t_next.lock().unwrap() {
192|                     s_next.on_next(v);
193|                 }
194|             })),
195|             on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
196|             on_completed: Mutex::new(Box::new(move || s_cmp.on_completed())),
197|         }));
198|         Subscription::empty()
199|     })
200| }
201| 
202| /// 发射，直到另一个 Observable 发射就立即终止。
203| ///
204| /// 一旦 `trigger` 发射，停止透传上游值并发出 `OnCompleted`。
205| ///
206| /// ## RxJS 对应
207| /// [takeUntil](https://rxjs.dev/api/operators/takeUntil)
208| pub fn take_until<T, E>(source: &crate::Observable<T, E>, trigger: &crate::Observable<(), E>) -> crate::Observable<T, E>
209| where
210|     E: Clone + Send + Sync + 'static,
211|     T: Send + Sync + 'static,
212| {
213|     let source_fn = source.subscribe_fn.clone();
214|     let stopped: Arc<Mutex<bool>> = Arc::new(Mutex::new(false));
215|     let stopped_t = stopped.clone();
216|     let stopped_s = stopped.clone();
217|     let stopped_next = stopped.clone();
218|     // 订阅 trigger，触发后停止
219|     trigger.subscribe(crate::observable::Callbacks {
220|         on_next: Mutex::new(Box::new(move |_| {
221|             if !*stopped_t.lock().unwrap() {
222|                 *stopped_t.lock().unwrap() = true;
223|             }
224|         })),
225|         on_error: Mutex::new(Box::new(move |_e: E| {
226|             if !*stopped_s.lock().unwrap() {
227|                 *stopped_s.lock().unwrap() = true;
228|             }
229|         })),
230|         on_completed: Mutex::new(Box::new(|| {})),
231|     });
232|     crate::Observable::<T, E>::new_impl(move |downstream| {
233|         let shared: Arc<dyn Observer<T, E>> = Arc::from(downstream);
234|         let s_next = shared.clone();
235|         let s_err = shared.clone();
236|         let s_cmp = shared.clone();
237|         let st_next = stopped_next.clone();
238|         let st_err = stopped_next.clone();
239|         let st_cmp = stopped_next.clone();
240|         source_fn(Box::new(Callbacks {
241|             on_next: Mutex::new(Box::new(move |v: T| {
242|                 if *st_next.lock().unwrap() { return; }
243|                 s_next.on_next(v);
244|             })),
245|             on_error: Mutex::new(Box::new(move |e| {
246|                 if *st_err.lock().unwrap() { return; }
247|                 s_err.on_error(e);
248|             })),
249|             on_completed: Mutex::new(Box::new(move || {
250|                 if *st_cmp.lock().unwrap() { return; }
251|                 s_cmp.on_completed();
252|             })),
253|         }));
254|         Subscription::empty()
255|     })
256| }
257| 
258| /// 丢弃连续重复的值（只比较相邻值）。
259| ///
260| /// 与 `distinct` 不同：`distinct_until_changed` 只丢弃**紧邻的重复值**。
261| /// 例如 `[1, 1, 2, 2, 2, 3, 3, 1]` → `[1, 2, 3, 1]`
262| ///
263| /// ## RxJS 对应
264| /// [distinctUntilChanged](https://rxjs.dev/api/operators/distinctUntilChanged)
265| pub fn distinct_until_changed<T, E>(source: &crate::Observable<T, E>) -> crate::Observable<T, E>
266| where
267|     T: Clone + PartialEq + Send + Sync + 'static,
268|     E: Send + Sync + Clone + 'static,
269| {
270|     let source_fn = source.subscribe_fn.clone();
271|     crate::Observable::<T, E>::new_impl(move |downstream| {
272|         let shared: Arc<dyn Observer<T, E>> = Arc::from(downstream);
273|         let last: Arc<Mutex<Option<T>>> = Arc::new(Mutex::new(None));
274|         let s_next = shared.clone();
275|         let s_err = shared.clone();
276|         let s_cmp = shared.clone();
277|         let last_next = last.clone();
278|         source_fn(Box::new(Callbacks {
279|             on_next: Mutex::new(Box::new(move |v: T| {
280|                 let mut guard = last_next.lock().unwrap();
281|                 match &*guard {
282|                     Some(prev) if *prev == v => return, // 跳过重复
283|                     _ => {}
284|                 }
285|                 *guard = Some(v.clone());
286|                 drop(guard);
287|                 s_next.on_next(v);
288|             })),
289|             on_error: Mutex::new(Box::new(move |e| s_err.on_error(e))),
290|             on_completed: Mutex::new(Box::new(move || s_cmp.on_completed())),
291|         }));
292|         Subscription::empty()
293|     })
294| }
